/*
 * DPoP (RFC 9449) proof signer for the k6 load tests.
 *
 * Builds a fresh signed DPoP proof JWT per request with a key generated by
 * certs/generate-certs.sh (dpop-keys.json: an array of the raw key components,
 * or a single object for backward compatibility). The signature is computed
 * with pure-JS asymmetric cryptography on BigInt, because the k6 crypto module
 * has no asymmetric signing support:
 *
 *   - EC P-256 keys (kty "EC", the generated ones): ES256 (ECDSA with SHA-256),
 *     the cheaper verification per proof on the bridge (see the recommendations
 *     in development-docs/LOAD-TESTING.md)
 *   - RSA keys (kty "RSA" or the legacy single-key files without kty): RS256
 *     (PKCS#1 v1.5 with SHA-256)
 *
 * The proof is bound to a single request (htm/htu claims) with a unique jti and
 * the current iat: the bridge validates the signature, the claims and the replay
 * cache per request.
 *
 * With the USERS knob (see the scenarios), each simulated user signs with its own
 * key of the pool (user i uses keys[(i-1) % keys.length]).
 */

import crypto from 'k6/crypto';
import encoding from 'k6/encoding';

// the key file is read at init time (relative paths resolve against this module's
// directory: lib/../../certs = scripts/load-test/certs)
const KEY_FILE = __ENV.DPOP_KEY_FILE || '../../certs/generated/dpop-keys.json';
const keys = JSON.parse(open(KEY_FILE));
const keyPool = Array.isArray(keys) ? keys : [keys];

// EC P-256 (prime256v1) domain parameters (SEC 2, section 2.4.2)
const P256 = {
    p: hexToBigInt('ffffffff00000001000000000000000000000000ffffffffffffffffffffffff'),
    a: hexToBigInt('ffffffff00000001000000000000000000000000fffffffffffffffffffffffc'),
    b: hexToBigInt('5ac635d8aa3a93e7b3ebbd55769886bc651d06b0cc53b0f63bce3c3e27d2604b'),
    n: hexToBigInt('ffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551'),
    gx: hexToBigInt('6b17d1f2e12c4247f8bce6e563a440f277037d812deb33a0f4a13945d898c296'),
    gy: hexToBigInt('4fe342e2fe1a7f9b8ee7eb4a7c0f9e162bce33576b315ececbb6406837bf51f5'),
};

function hexToBigInt(hex) {
  return hex === '' ? 0n : BigInt('0x' + hex);
}

function modexp(base, exp, mod) {
  let result = 1n;
  base %= mod;
  while (exp > 0n) {
    if (exp & 1n) {
      result = (result * base) % mod;
    }
    base = (base * base) % mod;
    exp >>= 1n;
  }
  return result;
}

function bigIntToBytes(value, length) {
  let hex = value.toString(16);
  if (hex.length % 2 === 1) {
    hex = '0' + hex;
  }
  const bytes = new Uint8Array(length);
  const offset = length - hex.length / 2;
  for (let i = 0; i < hex.length / 2; i++) {
    bytes[offset + i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return bytes;
}

function base64Url(data) {
  // base64 of the bytes of the provided string or ArrayBuffer, adapted to base64url
  const encoded = encoding.b64encode(data);
  return encoded.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function rsaSignSha256(signingInput, key) {
  const modulusBytes = Math.ceil(key.n.length / 2);
  const digestInfo = key.digestInfo + crypto.sha256(signingInput, 'hex');
  const digestInfoBytes = digestInfo.length / 2;
  // PKCS#1 v1.5: 00 01 FF..FF 00 DigestInfo (padded to the modulus length)
  const paddingLength = modulusBytes - digestInfoBytes - 3;
  if (paddingLength < 8) {
    throw new Error('RSA modulus too small for the signature');
  }
  const em = '0001' + 'ff'.repeat(paddingLength) + '00' + digestInfo;
  const signature = modexp(hexToBigInt(em), hexToBigInt(key.d), hexToBigInt(key.n));
  return base64Url(bigIntToBytes(signature, modulusBytes).buffer);
}

// --- ECDSA P-256 (ES256), with the point arithmetic on Jacobian coordinates ---

// point at infinity in Jacobian coordinates (Z = 0)
const INFINITY = { x: 1n, y: 1n, z: 0n };

function jacobianDouble(point, curve) {
  // point at infinity or Y = 0: the result is the point at infinity
  if (point.z === 0n || point.y === 0n) {
    return INFINITY;
  }
  const { a, p } = curve;
  const y2 = (point.y * point.y) % p;
  const d = (4n * point.x * y2) % p;
  const c = (y2 * y2) % p;
  const e = (3n * point.x * point.x + a * modexp(point.z, 4n, p)) % p;
  const f = (e * e) % p;
  const x3 = (f - 2n * d + 2n * p) % p;
  const y3 = (e * ((d - x3 + p) % p) - 8n * c + 4n * p) % p;
  const z3 = (2n * point.y * point.z) % p;
  return { x: x3, y: y3, z: z3 };
}

function jacobianAdd(point1, point2, curve) {
  const { p } = curve;
  if (point1.z === 0n) {
    return point2;
  }
  if (point2.z === 0n) {
    return point1;
  }
  const z1z1 = (point1.z * point1.z) % p;
  const z2z2 = (point2.z * point2.z) % p;
  const u1 = (point1.x * z2z2) % p;
  const u2 = (point2.x * z1z1) % p;
  const s1 = (point1.y * point2.z % p * z2z2) % p;
  const s2 = (point2.y * point1.z % p * z1z1) % p;
  const h = (u2 - u1 + p) % p;
  const r = (2n * (s2 - s1 + p)) % p;
  if (h === 0n) {
    return r === 0n ? jacobianDouble(point1, curve) : INFINITY;
  }
  const i = modexp(2n * h, 2n, p);
  const j = (h * i) % p;
  const v = (u1 * i) % p;
  const x3 = ((r * r - j - 2n * v) % p + 2n * p) % p;
  const y3 = (r * ((v - x3 + p) % p) - 2n * s1 * j + 2n * p * p) % p;
  const z3 = (modexp(point1.z + point2.z, 2n, p) - z1z1 - z2z2 + 2n * p) % p * h % p;
  return { x: x3, y: y3, z: z3 };
}

function jacobianMultiply(scalar, curve) {
  // double-and-add from the most significant bit
  let result = INFINITY;
  let addend = { x: curve.gx, y: curve.gy, z: 1n };
  let k = scalar;
  while (k > 0n) {
    if (k & 1n) {
      result = jacobianAdd(result, addend, curve);
    }
    addend = jacobianDouble(addend, curve);
    k >>= 1n;
  }
  return result;
}

function jacobianToAffine(point, curve) {
  if (point.z === 0n) {
    throw new Error('Cannot convert the point at infinity to affine coordinates');
  }
  const { p } = curve;
  const zInv = modexp(point.z, p - 2n, p);
  const zInv2 = (zInv * zInv) % p;
  const zInv3 = (zInv2 * zInv) % p;
  return { x: (point.x * zInv2) % p, y: (point.y * zInv3) % p };
}

function ecdsaSignP256(signingInput, key) {
  const curve = P256;
  const d = hexToBigInt(key.d);
  // the SHA-256 digest is exactly the order of magnitude of the P-256 subgroup:
  // no bit truncation needed
  const z = hexToBigInt(crypto.sha256(signingInput, 'hex'));
  let r, s;
  do {
    // random nonce in [1, n - 1]
    let k;
    do {
      const nonceBytes = new Uint8Array(crypto.randomBytes(32));
      let nonceHex = '';
      for (const byte of nonceBytes) {
        nonceHex += byte.toString(16).padStart(2, '0');
      }
      k = hexToBigInt(nonceHex) % curve.n;
    } while (k === 0n);

    const point = jacobianToAffine(jacobianMultiply(k, curve), curve);
    r = point.x % curve.n;
    s = modexp(k, curve.n - 2n, curve.n) * ((z + r * d) % curve.n) % curve.n;
    if (s > curve.n / 2n) {
      // low-S normalization (some verifiers reject high-S signatures)
      s = curve.n - s;
    }
  } while (r === 0n || s === 0n);

  // the JWS ES256 signature is the raw r || s concatenation (64 bytes), not DER
  const signature = new Uint8Array(64);
  signature.set(bigIntToBytes(r, 32), 0);
  signature.set(bigIntToBytes(s, 32), 32);
  return base64Url(signature.buffer);
}

/**
 * Build a signed DPoP proof (JWT compact serialization) for the provided HTTP
 * method and target URI, with a fresh unique identifier (jti) and the current
 * time (iat)
 *
 * @param httpMethod the HTTP method of the request (htm claim)
 * @param htu        the HTTP target URI of the request, without query and fragment (htu claim)
 * @return the DPoP proof
 */
export function dpopProof(httpMethod, htu) {
  // each simulated user (USERS knob) signs with its own key of the pool; the key
  // index matches the user index of the credentials in the scenarios (the safe
  // modulo handles the teardown VU, id 0)
  const users = parseInt(__ENV.USERS || '1');
  const userIndex = (((__VU - 1) % users) + users) % users;
  const key = keyPool[userIndex % keyPool.length];

  const isEc = key.kty === 'EC';
  const header = isEc
    ? {
        alg: 'ES256',
        typ: 'dpop+jwt',
        jwk: {
          kty: 'EC',
          crv: 'P-256',
          x: base64Url(bigIntToBytes(hexToBigInt(key.x), 32).buffer),
          y: base64Url(bigIntToBytes(hexToBigInt(key.y), 32).buffer),
        },
      }
    : {
        alg: 'RS256',
        typ: 'dpop+jwt',
        jwk: {
          kty: 'RSA',
          n: base64Url(bigIntToBytes(hexToBigInt(key.n), Math.ceil(key.n.length / 2)).buffer),
          e: base64Url(bigIntToBytes(hexToBigInt(key.e), Math.ceil(key.e.length / 2)).buffer),
        },
      };
  const claims = {
    htm: httpMethod,
    htu: htu,
    iat: Math.floor(Date.now() / 1000),
    // a unique identifier per proof (the bridge rejects replayed proofs)
    jti: Date.now().toString(36) + '-' + Math.random().toString(36).slice(2),
  };
  const headerPart = base64Url(JSON.stringify(header));
  const payloadPart = base64Url(JSON.stringify(claims));
  const signingInput = headerPart + '.' + payloadPart;
  const signature = isEc ? ecdsaSignP256(signingInput, key) : rsaSignSha256(signingInput, key);
  return signingInput + '.' + signature;
}
